if(!defined('WHMCS'))die('Direct access denied');require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/migrations/V100.php';require_once __DIR__.'/migrations/V110.php';require_once __DIR__.'/migrations/V120.php';require_once __DIR__.'/migrations/V130.php';require_once __DIR__.'/migrations/V140.php';require_once __DIR__.'/migrations/V150.php';
use CloudHost247\Foundation\Database\MigrationRunner;use CloudHost247\Ovh\Migrations\OvhInitialMigration;use CloudHost247\Ovh\Migrations\OvhOperationalMigration;use CloudHost247\Ovh\Migrations\OvhParityMigration;use CloudHost247\Ovh\Migrations\OvhDiscoveryMigration;use CloudHost247\Ovh\Migrations\HostingProductMigration;use CloudHost247\Ovh\Services\AdminController;
function cloudhost247_ovh_config(){return array('name'=>'CloudHost247 OVH','description'=>'Independent authenticated OVH catalog, mapping, provisioning and synchronization.','version'=>'1.3.0','author'=>'CloudHost247','language'=>'english','fields'=>array());}
function cloudhost247_ovh_activate(){try{$a=(new MigrationRunner())->run('cloudhost247_ovh',array(new OvhInitialMigration(),new OvhOperationalMigration(),new OvhParityMigration(),new OvhDiscoveryMigration(),new HostingProductMigration(),new \CloudHost247\Ovh\Migrations\PricingEvidenceMigration()));return array('status'=>'success','description'=>'OVH integration installed: '.($a?implode(', ',$a):'already current'));}catch(\Throwable$e){return array('status'=>'error','description'=>$e->getMessage());}}
function cloudhost247_ovh_deactivate(){return array('status'=>'success','description'=>'Data retained. OVH and WHMCS services were not modified or removed.');}
function cloudhost247_ovh_output($vars)
{
